diff --git a/project/MetaOptimize/TrafficEngineering/Candidate/CutSearch.cs b/project/MetaOptimize/TrafficEngineering/Candidate/CutSearch.cs
new file mode 100644
index 0000000..c330aaf
--- /dev/null
+++ b/project/MetaOptimize/TrafficEngineering/Candidate/CutSearch.cs
@@ -0,0 +1,360 @@
+namespace MetaOptimize;
+
+using System.Diagnostics;
+using System.Numerics;
+
+/// <summary>
+/// A nonnegative edge price gives an upper bound on the throughput of the residual
+/// packing LP. At unit prices on a set of edges, a large pair contributes to
+/// the dual deficit if every path meets the set. A pin contributes once for
+/// each priced edge on its first path. Search the associated linear bounds.
+/// </summary>
+internal sealed class CutSearch
+{
+    private const double Epsilon = 1e-7;
+    private readonly AdversarialSearchInstance data;
+    private readonly DemandOptimizer optimizer;
+    private readonly SharedIncumbent global;
+    private readonly Stopwatch timer;
+    private readonly int limitMs;
+    private readonly int n;
+    private readonly int density;
+    private readonly uint[,] pathUsers;
+    private readonly uint[,] shortestLayers;
+    private readonly int[] selected;
+    private readonly double[] smallRaw;
+    private readonly double[] largeRaw;
+    private readonly double[] smallBenefit;
+    private readonly int[] pairOrder;
+    private readonly double[,,] upper;
+    private readonly int worker;
+    private readonly int workers;
+    private readonly int[] shortCounts;
+    private readonly int[] gainCounts;
+    private readonly uint[] witnessPairs;
+    private readonly int[] usefulEdges;
+    private bool stop;
+    private double cutCost;
+    private double best;
+    private int nodes;
+    private int fullChecks;
+
+    public CutSearch(AdversarialSearchInstance data, DemandOptimizer optimizer, SharedIncumbent global, Stopwatch timer, int limitMs, int worker, int workers)
+    {
+        this.data = data;
+        this.optimizer = optimizer;
+        this.global = global;
+        this.timer = timer;
+        this.limitMs = limitMs;
+        this.worker = worker;
+        this.workers = workers;
+        this.n = data.Pairs.Length;
+        this.density = data.DensityLimit;
+        this.pathUsers = new uint[data.Edges.Length, 4];
+        for (int i = 0; i < this.n; i++)
+        {
+            var paths = data.Pairs[i].Paths;
+            for (int j = 0; j < 4; j++)
+            {
+                foreach (int edge in paths[j < paths.Length ? j : 0])
+                {
+                    this.pathUsers[edge, j] |= 1U << i;
+                }
+            }
+        }
+
+        var usedEdges = new List<int>();
+        for (int e = 0; e < data.Edges.Length; e++)
+        {
+            if ((this.pathUsers[e, 0] | this.pathUsers[e, 1] | this.pathUsers[e, 2] | this.pathUsers[e, 3]) != 0)
+            {
+                usedEdges.Add(e);
+            }
+        }
+
+        this.usefulEdges = usedEdges.ToArray();
+        this.selected = new int[9];
+        this.shortestLayers = new uint[10, 10];
+        this.shortCounts = new int[10];
+        this.gainCounts = new int[10];
+        this.witnessPairs = new uint[9];
+        this.smallRaw = new double[this.n];
+        this.largeRaw = new double[this.n];
+        this.smallBenefit = new double[this.n];
+        this.pairOrder = new int[this.n];
+        this.upper = new double[5, this.n + 1, this.density + 1];
+    }
+
+    public void Run()
+    {
+        for (int size = 1; size <= 7 && size <= this.usefulEdges.Length; size++)
+        {
+            for (int first = this.worker; first <= this.usefulEdges.Length - size; first += this.workers)
+            {
+                if (this.Expired())
+                {
+                    return;
+                }
+
+                int e = this.usefulEdges[first];
+                this.selected[0] = e;
+                this.shortestLayers[1, 1] = this.pathUsers[e, 0];
+                this.Extend(size, first + 1, 1, this.data.Edges[e].Capacity, this.pathUsers[e, 0], this.pathUsers[e, 1],
+                    this.pathUsers[e, 2], this.pathUsers[e, 3], 0, 0, 0, 0);
+            }
+        }
+    }
+
+    private bool Expired() => this.stop |= this.timer.ElapsedMilliseconds >= this.limitMs;
+
+    // a..d mark pairs whose respective path meets the cut. aa..dd mark paths hit twice.
+    private void Extend(int size, int first, int depth, double cost, uint a, uint b, uint c, uint d, uint aa, uint bb, uint cc, uint dd)
+    {
+        if (depth == size)
+        {
+            uint covered = a & b & c & d;
+            if (covered == 0)
+            {
+                return;
+            }
+
+            for (int i = 0; i < depth; i++)
+            {
+                int e = this.selected[i];
+                uint indispensable = covered & ((this.pathUsers[e, 0] & ~aa) | (this.pathUsers[e, 1] & ~bb)
+                    | (this.pathUsers[e, 2] & ~cc) | (this.pathUsers[e, 3] & ~dd));
+                if (indispensable == 0)
+                {
+                    return;
+                }
+
+                this.witnessPairs[i] = indispensable;
+            }
+
+            this.TestCut(covered, depth, cost);
+            return;
+        }
+
+        if (this.stop || ((++this.nodes & 511) == 0 && this.Expired()))
+        {
+            return;
+        }
+
+        for (int i = first; i <= this.usefulEdges.Length - (size - depth); i++)
+        {
+            int e = this.usefulEdges[i];
+            uint u = this.pathUsers[e, 0], v = this.pathUsers[e, 1], w = this.pathUsers[e, 2], x = this.pathUsers[e, 3];
+            this.selected[depth] = e;
+            this.shortestLayers[depth + 1, 1] = a | u;
+            for (int k = 2; k <= depth + 1; k++)
+            {
+                this.shortestLayers[depth + 1, k] = this.shortestLayers[depth, k] | (this.shortestLayers[depth, k - 1] & u);
+            }
+
+            this.Extend(size, i + 1, depth + 1, cost + this.data.Edges[e].Capacity,
+                a | u, b | v, c | w, d | x, aa | (a & u), bb | (b & v), cc | (c & w), dd | (d & x));
+        }
+    }
+
+    private void TestCut(uint covered, int depth, double cost)
+    {
+        this.best = this.global.Value;
+        double lo = this.data.Levels[1], hi = this.data.Levels[2];
+        int coverCount = BitOperations.PopCount(covered);
+        for (int m = 1; m <= depth; m++)
+        {
+            uint mask = this.shortestLayers[depth, m];
+            this.shortCounts[m] = BitOperations.PopCount(mask);
+            this.gainCounts[m] = BitOperations.PopCount((mask & ~covered) | (this.shortestLayers[depth, m + 1] & covered));
+        }
+
+        bool viable = false;
+        for (int s = 1; s < this.density; s++)
+        {
+            int hit = 0, gain = 0;
+            for (int m = 1; m <= depth; m++)
+            {
+                hit += Math.Min(s, this.shortCounts[m]);
+                gain += Math.Min(s, this.gainCounts[m]);
+            }
+
+            if (lo * gain > this.best + Epsilon && (lo * hit) + (hi * Math.Min(this.density - s, coverCount)) - cost > this.best + Epsilon)
+            {
+                viable = true;
+                break;
+            }
+        }
+
+        if (!viable || this.Expired())
+        {
+            return;
+        }
+
+        this.cutCost = cost;
+        for (int i = 0; i < this.n; i++)
+        {
+            int count = 0;
+            for (int m = 1; m <= depth; m++)
+            {
+                count += (int)((this.shortestLayers[depth, m] >> i) & 1U);
+            }
+
+            int hit = (int)((covered >> i) & 1U);
+            this.smallRaw[i] = lo * count;
+            this.smallBenefit[i] = lo * (count - hit);
+            this.largeRaw[i] = hi * hit;
+        }
+
+        this.SearchPrice(depth);
+    }
+
+    private void SearchPrice(int depth)
+    {
+        // Consider pairs that can contribute to the residual LP deficit first. Others
+        // can still help against POP, even if they give no benefit for this price.
+        int end = 0;
+        for (int i = 0; i < this.n; i++)
+        {
+            if (this.smallRaw[i] > Epsilon || this.largeRaw[i] > Epsilon)
+            {
+                this.pairOrder[end++] = i;
+            }
+        }
+
+        Array.Sort(this.pairOrder, 0, end, Comparer<int>.Create((i, j) =>
+            (this.largeRaw[j] + this.smallBenefit[j] + this.smallRaw[j]).CompareTo(this.largeRaw[i] + this.smallBenefit[i] + this.smallRaw[i])));
+        // For a fixed price, deficit(DP) - deficit(OPT) is bounded by both the
+        // DP deficit expression and the saving on reroutable pinned traffic.
+        // Convex combinations tighten these bounds over undecided pair choices.
+        for (int j = 0; j < 5; j++)
+        {
+            double t = j * 0.25;
+            for (int k = 1; k <= this.density; k++)
+            {
+                this.upper[j, end, k] = 0;
+            }
+
+            for (int p = end - 1; p >= 0; p--)
+            {
+                int i = this.pairOrder[p];
+                double v = Math.Max((1 - t) * this.largeRaw[i], ((1 - t) * this.smallRaw[i]) + (t * this.smallBenefit[i]));
+                for (int k = 1; k <= this.density; k++)
+                {
+                    this.upper[j, p, k] = Math.Max(this.upper[j, p + 1, k], v + this.upper[j, p + 1, k - 1]);
+                }
+            }
+
+            if (this.upper[j, 0, this.density] - ((1 - t) * this.cutCost) <= this.best + Epsilon)
+            {
+                return;
+            }
+        }
+
+        this.fullChecks = 0;
+        this.Assign(0, end, this.density, 0, 0, -this.cutCost, 0, depth);
+    }
+
+    private void Assign(int p, int end, int slots, int small, int large, double raw, double benefit, int depth)
+    {
+        if (this.stop || this.fullChecks > 80000 || ((++this.nodes & 2047) == 0 && this.Expired()))
+        {
+            return;
+        }
+
+        if (slots == 0 || p == end)
+        {
+            if (Math.Min(raw, benefit) > this.best + Epsilon)
+            {
+                for (int e = 0; e < depth; e++)
+                {
+                    if ((this.witnessPairs[e] & (uint)large) == 0)
+                    {
+                        return;
+                    }
+                }
+
+                this.Fill(small, large, 0, slots, raw);
+            }
+
+            return;
+        }
+
+        if (raw + this.upper[0, p, slots] <= this.best + Epsilon ||
+            benefit + this.upper[4, p, slots] <= this.best + Epsilon ||
+            (0.5 * (raw + benefit)) + this.upper[2, p, slots] <= this.best + Epsilon ||
+            (0.25 * raw) + (0.75 * benefit) + this.upper[3, p, slots] <= this.best + Epsilon ||
+            (0.75 * raw) + (0.25 * benefit) + this.upper[1, p, slots] <= this.best + Epsilon)
+        {
+            return;
+        }
+
+        int i = this.pairOrder[p];
+        int bit = 1 << i;
+        if (this.largeRaw[i] > Epsilon)
+        {
+            this.Assign(p + 1, end, slots - 1, small, large | bit, raw + this.largeRaw[i], benefit, depth);
+        }
+
+        if (this.smallRaw[i] > Epsilon)
+        {
+            this.Assign(p + 1, end, slots - 1, small | bit, large, raw + this.smallRaw[i], benefit + this.smallBenefit[i], depth);
+        }
+
+        this.Assign(p + 1, end, slots, small, large, raw, benefit, depth);
+    }
+
+    private void Fill(int small, int large, int start, int slots, double raw)
+    {
+        if (this.stop || ((++this.fullChecks & 511) == 0 && this.Expired()))
+        {
+            return;
+        }
+
+        var score = this.optimizer.Score(new Matrix(small, large));
+        if (score.Gap > this.best + Epsilon)
+        {
+            this.global.Improve(score.Gap);
+            this.best = this.global.Value;
+        }
+
+        // Unpriced pairs can only increase the optimal-routing deficit.
+        if (slots == 0 || raw - score.OptimalLoss <= this.best + Epsilon || this.fullChecks > 80000)
+        {
+            return;
+        }
+
+        for (int i = start; i < this.n; i++)
+        {
+            int bit = 1 << i;
+            if (((small | large) & bit) != 0)
+            {
+                continue;
+            }
+
+            if (this.largeRaw[i] < Epsilon)
+            {
+                this.Fill(small, large | bit, i + 1, slots - 1, raw);
+            }
+
+            if (this.smallRaw[i] < Epsilon)
+            {
+                this.Fill(small | bit, large, i + 1, slots - 1, raw);
+            }
+        }
+    }
+}
+
+internal sealed class SharedIncumbent
+{
+    private double gap;
+
+    public double Value => Volatile.Read(ref this.gap);
+
+    public void Improve(double value)
+    {
+        lock (this)
+        {
+            this.gap = Math.Max(value, this.gap);
+        }
+    }
+}
diff --git a/project/MetaOptimize/TrafficEngineering/Candidate/DemandOptimizer.cs b/project/MetaOptimize/TrafficEngineering/Candidate/DemandOptimizer.cs
new file mode 100644
index 0000000..13ae5b6
--- /dev/null
+++ b/project/MetaOptimize/TrafficEngineering/Candidate/DemandOptimizer.cs
@@ -0,0 +1,217 @@
+namespace MetaOptimize;
+
+using System.Diagnostics;
+
+internal readonly record struct Matrix(int Small, int Large)
+{
+    public int[] Levels(int n)
+    {
+        var answer = new int[n];
+        for (int i = 0; i < n; i++)
+        {
+            int bit = 1 << i;
+            answer[i] = (this.Large & bit) != 0 ? 2 : ((this.Small & bit) != 0 ? 1 : 0);
+        }
+
+        return answer;
+    }
+}
+
+internal sealed class DemandOptimizer
+{
+    private readonly AdversarialSearchInstance data;
+    private readonly FlowSolver solver;
+    private readonly Random random;
+    private readonly int all;
+    private readonly Dictionary<Matrix, double>[] popCache;
+    private readonly int[] partitionMasks;
+    private readonly Dictionary<Matrix, (double Gap, double Energy, double OptimalLoss)> cache = new Dictionary<Matrix, (double Gap, double Energy, double OptimalLoss)>();
+    private readonly Stopwatch timer;
+    private readonly List<(Matrix Matrix, double Gap)> elites = new List<(Matrix Matrix, double Gap)>();
+    private readonly HashSet<Matrix> eliteSet = new HashSet<Matrix>();
+
+    public DemandOptimizer(AdversarialSearchInstance data, int seed, Stopwatch timer)
+    {
+        this.data = data;
+        this.random = new Random(seed);
+        this.solver = new FlowSolver(data);
+        this.timer = timer;
+        this.all = (1 << data.Pairs.Length) - 1;
+        this.popCache = new Dictionary<Matrix, double>[data.PopPartitions];
+        this.partitionMasks = new int[data.PopPartitions];
+        for (int k = 0; k < data.PopPartitions; k++)
+        {
+            this.popCache[k] = new Dictionary<Matrix, double>();
+        }
+
+        for (int i = 0; i < data.Pairs.Length; i++)
+        {
+            this.partitionMasks[data.Pairs[i].Partition] |= 1 << i;
+        }
+    }
+
+    public (Matrix Matrix, double Gap) Best => this.elites.Count > 0 ? this.elites[0] : (default, 0);
+
+    public void Run()
+    {
+        int steps = 1200;
+        for (int epoch = 0; epoch < 160 && this.timer.ElapsedMilliseconds < 6500; epoch++)
+        {
+            Matrix state = default;
+            if (this.elites.Count > 0 && epoch % 3 > 0)
+            {
+                state = this.elites[this.random.Next(this.elites.Count)].Matrix;
+                for (int j = 0; j < 1 + (epoch % 5); j++)
+                {
+                    state = this.Move(state);
+                }
+            }
+            else
+            {
+                int small = 2 + this.random.Next(this.data.DensityLimit - 3);
+                for (int j = 0; j < this.data.DensityLimit; j++)
+                {
+                    int bit = this.Pick(this.all ^ (state.Small | state.Large));
+                    state = j < small ? state with { Small = state.Small | bit }
+                        : state with { Large = state.Large | bit };
+                }
+            }
+
+            var current = this.Score(state);
+            double temperature = epoch % 3 == 0 ? 5.0 : 2.8;
+            double cooling = Math.Pow(0.13 / temperature, 1.0 / steps);
+            for (int step = 0; step < steps; step++)
+            {
+                var next = this.Move(state);
+                var score = this.Score(next);
+                if (score.Energy >= current.Energy ||
+                    this.random.NextDouble() < Math.Exp((score.Energy - current.Energy) / temperature))
+                {
+                    state = next;
+                    current = score;
+                }
+
+                temperature *= cooling;
+            }
+        }
+
+        // Explore sparse neighbors of the best full-density annealing states.
+        // In particular, dropping a demand can increase optimal throughput
+        // relative to the combined heuristic.
+        for (int i = 0; i < Math.Min(6, this.elites.Count) && this.timer.ElapsedMilliseconds < 6800; i++)
+        {
+            Matrix m = this.elites[i].Matrix;
+            int active = m.Small | m.Large;
+            for (int bits = active; bits != 0; bits &= bits - 1)
+            {
+                int bit = bits & -bits;
+                var reduced = new Matrix(m.Small & ~bit, m.Large & ~bit);
+                this.Score(reduced);
+                this.Score(new Matrix(m.Small ^ bit, m.Large ^ bit));
+                for (int outside = this.all ^ active; outside != 0; outside &= outside - 1)
+                {
+                    int added = outside & -outside;
+                    this.Score(reduced with { Small = reduced.Small | added });
+                    this.Score(reduced with { Large = reduced.Large | added });
+                }
+            }
+        }
+    }
+
+    private int Pick(int mask)
+    {
+        int p = this.random.Next(FlowSolver.Count(mask));
+        while (p-- > 0)
+        {
+            mask &= mask - 1;
+        }
+
+        return mask & -mask;
+    }
+
+    private Matrix Move(Matrix m)
+    {
+        int inactive = this.all ^ (m.Small | m.Large);
+        int type = this.random.Next(12);
+        int a = this.Pick(m.Small | m.Large);
+        int b = this.Pick(inactive);
+        if (type == 0 && m.Small != 0 && m.Large != 0)
+        {
+            int change = this.Pick(m.Small) | this.Pick(m.Large);
+            return new Matrix(m.Small ^ change, m.Large ^ change);
+        }
+
+        if (type <= 2)
+        {
+            return new Matrix(m.Small ^ a, m.Large ^ a);
+        }
+
+        bool small = (m.Small & a) != 0;
+        if (type <= 4)
+        {
+            small = !small;
+        }
+
+        return new Matrix((m.Small & ~a) | (small ? b : 0), (m.Large & ~a) | (small ? 0 : b));
+    }
+
+    public (double Gap, double Energy, double OptimalLoss) Score(Matrix m)
+    {
+        if (this.cache.TryGetValue(m, out var item))
+        {
+            return item;
+        }
+
+        double dp = this.solver.Loss(0, m.Large, m.Small, 1.0);
+        if (double.IsPositiveInfinity(dp))
+        {
+            return (-1000, -1000, double.PositiveInfinity);
+        }
+
+        if (!this.solver.IsOptimal)
+        {
+            dp = 0;
+        }
+
+        double pop = 0;
+        for (int k = 0; k < this.popCache.Length; k++)
+        {
+            int mask = this.partitionMasks[k];
+            var part = new Matrix(m.Small & mask, m.Large & mask);
+            if (!this.popCache[k].TryGetValue(part, out var loss))
+            {
+                loss = this.solver.Loss(part.Small, part.Large, 0, 1.0 / this.data.PopPartitions);
+                if (!this.solver.IsOptimal)
+                {
+                    loss = 0;
+                }
+
+                this.popCache[k].Add(part, loss);
+            }
+
+            pop += loss;
+        }
+
+        double opt = this.solver.Loss(m.Small, m.Large, 0, 1.0);
+        double gap = Math.Min(dp, pop) - opt;
+        item = (gap, gap + (0.015 * (dp - opt)) + (0.001 * (pop - opt)), this.solver.IsOptimal ? opt : 0);
+        if (this.cache.Count >= 350000)
+        {
+            this.cache.Clear();
+        }
+
+        this.cache.Add(m, item);
+        if ((this.elites.Count < 24 || gap > this.elites[^1].Gap + 1e-7) && this.eliteSet.Add(m))
+        {
+            int pos = this.elites.FindIndex(e => e.Gap < gap);
+            this.elites.Insert(pos < 0 ? this.elites.Count : pos, (m, gap));
+            if (this.elites.Count > 24)
+            {
+                this.eliteSet.Remove(this.elites[^1].Matrix);
+                this.elites.RemoveAt(this.elites.Count - 1);
+            }
+        }
+
+        return item;
+    }
+}
diff --git a/project/MetaOptimize/TrafficEngineering/Candidate/FlowSolver.cs b/project/MetaOptimize/TrafficEngineering/Candidate/FlowSolver.cs
new file mode 100644
index 0000000..bc09626
--- /dev/null
+++ b/project/MetaOptimize/TrafficEngineering/Candidate/FlowSolver.cs
@@ -0,0 +1,389 @@
+namespace MetaOptimize;
+
+using System.Numerics;
+using System.Runtime.CompilerServices;
+
+/// <summary>
+/// Small packing LP with demand rows and edge rows. The initial slack basis is feasible.
+/// </summary>
+internal sealed class FlowSolver
+{
+    private const double Epsilon = 1e-9;
+    private readonly AdversarialSearchInstance data;
+    private readonly int[] users;
+    private readonly int[] pinnedUsers;
+    private readonly double[] capacities;
+    private readonly int[] edgeRows;
+    private readonly int[] basic;
+    private readonly int[] nonbasic;
+    private readonly int stride;
+    private readonly double[] table;
+    private readonly int[] pairList;
+    private readonly int[] pathList;
+    private readonly ulong[] pathMasks;
+
+    public FlowSolver(AdversarialSearchInstance data)
+        : this(data, data.DensityLimit)
+    {
+    }
+
+    public FlowSolver(AdversarialSearchInstance data, int maxActive)
+    {
+        this.data = data;
+        int edges = data.Edges.Length;
+        this.users = new int[edges];
+        this.pinnedUsers = new int[edges];
+        this.capacities = new double[edges];
+        this.edgeRows = new int[edges];
+        for (int i = 0; i < data.Pairs.Length; i++)
+        {
+            foreach (var path in data.Pairs[i].Paths)
+            {
+                foreach (int edge in path)
+                {
+                    this.users[edge] |= 1 << i;
+                }
+            }
+
+            foreach (int edge in data.Pairs[i].Paths[0])
+            {
+                this.pinnedUsers[edge] |= 1 << i;
+            }
+        }
+
+        int maxPaths = 0;
+        foreach (var pair in data.Pairs)
+        {
+            maxPaths = Math.Max(maxPaths, pair.Paths.Length);
+        }
+
+        this.pathMasks = new ulong[maxPaths];
+        int maxColumns = this.pathMasks.Length * maxActive;
+        this.pairList = new int[maxColumns];
+        this.pathList = new int[maxColumns];
+        this.stride = maxColumns + 1;
+        this.basic = new int[edges + maxActive + 1];
+        this.nonbasic = new int[maxColumns + 1];
+        this.table = new double[this.basic.Length * this.stride];
+    }
+
+    public bool IsOptimal { get; private set; }
+
+    [MethodImpl(MethodImplOptions.AggressiveInlining)]
+    internal static int Count(int mask) => BitOperations.PopCount((uint)mask);
+
+    [MethodImpl(MethodImplOptions.AggressiveInlining)]
+    internal static int First(int mask) => BitOperations.TrailingZeroCount((uint)mask);
+
+    // Returns unmet demand. For DP, 'pinned' has already been assigned its first paths.
+    public double Loss(int small, int large, int pinned, double scale)
+        => this.Solve(small, large, pinned, scale, null, null);
+
+    public double Solve(int small, int large, int pinned, double scale, double[] bounds, FlowRoute route, double lowDemand = -1, double lossThreshold = -1)
+    {
+        this.IsOptimal = true;
+        route?.Reset();
+        double low = lowDemand < 0 ? this.data.Levels[1] : lowDemand;
+        double high = this.data.Levels[2];
+        int rows = 0;
+        for (int e = 0; e < this.capacities.Length; e++)
+        {
+            double free = bounds != null ? bounds[e] : (this.data.Edges[e].Capacity * scale) - (low * Count(pinned & this.pinnedUsers[e]));
+            if (free < -1e-7)
+            {
+                return double.PositiveInfinity;
+            }
+
+            int users = this.users[e];
+            if ((low * Count(small & users)) + (high * Count(large & users)) > free + Epsilon)
+            {
+                this.capacities[rows] = Math.Max(0, free);
+                this.edgeRows[e] = ++rows;
+            }
+            else
+            {
+                this.edgeRows[e] = 0;
+            }
+        }
+
+        if (rows == 0)
+        {
+            if (route != null)
+            {
+                for (int bits = small | large; bits != 0; bits &= bits - 1)
+                {
+                    int i = First(bits);
+                    route.Add(i, 0, ((1 << i) & small) != 0 ? low : high);
+                }
+            }
+
+            return 0;
+        }
+
+        int edgeCount = rows;
+        int columns = 0;
+        int active = small | large;
+        int independent = 0;
+        for (int bits = active; bits != 0; bits &= bits - 1)
+        {
+            int i = First(bits);
+            var paths = this.data.Pairs[i].Paths;
+            bool unconstrained = false;
+            for (int j = 0; j < paths.Length; j++)
+            {
+                ulong mask = 0;
+                foreach (int edge in paths[j])
+                {
+                    int row = this.edgeRows[edge];
+                    if (row != 0)
+                    {
+                        mask |= 1UL << (row - 1);
+                    }
+                }
+
+                if (mask == 0)
+                {
+                    route?.Add(i, j, ((1 << i) & small) != 0 ? low : high);
+                    unconstrained = true;
+                    break;
+                }
+
+                this.pathMasks[j] = mask;
+            }
+
+            if (unconstrained)
+            {
+                independent |= 1 << i;
+                continue;
+            }
+
+            for (int j = 0; j < paths.Length; j++)
+            {
+                bool dominated = false;
+                if (edgeCount <= 64)
+                {
+                    ulong mask = this.pathMasks[j];
+                    for (int k = 0; k < paths.Length; k++)
+                    {
+                        ulong other = this.pathMasks[k];
+                        if ((other & mask) == other && (other != mask || k < j))
+                        {
+                            dominated = true;
+                            break;
+                        }
+                    }
+                }
+
+                if (!dominated)
+                {
+                    this.pairList[columns] = i;
+                    this.pathList[columns++] = j;
+                }
+            }
+        }
+
+        if (columns == 0)
+        {
+            return 0;
+        }
+
+        rows += Count(active ^ independent);
+        int width = this.stride;
+        var t = this.table;
+        for (int r = 0; r <= rows; r++)
+        {
+            Array.Clear(t, r * width, columns + 1);
+        }
+
+        for (int r = 1; r <= edgeCount; r++)
+        {
+            t[r * width] = this.capacities[r - 1];
+        }
+
+        int pairRow = edgeCount;
+        int prev = -1;
+        for (int j = 1; j <= columns; j++)
+        {
+            int i = this.pairList[j - 1];
+            if (i != prev)
+            {
+                t[++pairRow * width] = ((1 << i) & small) != 0 ? low : high;
+                prev = i;
+            }
+
+            t[j] = 1;
+            t[(pairRow * width) + j] = 1;
+            foreach (int e in this.data.Pairs[i].Paths[this.pathList[j - 1]])
+            {
+                int r = this.edgeRows[e];
+                if (r != 0)
+                {
+                    t[(r * width) + j] = 1;
+                }
+            }
+
+            this.nonbasic[j] = j;
+        }
+
+        for (int r = 1; r <= rows; r++)
+        {
+            this.basic[r] = r + columns;
+        }
+
+        double demand = (low * Count(small & ~independent)) + (high * Count(large & ~independent));
+        // Row zero stores reduced costs and the negative of the current objective.
+        for (int iteration = 0; ; iteration++)
+        {
+            if (lossThreshold >= 0 && demand + t[0] <= lossThreshold + Epsilon)
+            {
+                this.IsOptimal = false;
+                // The current basic solution already supplies the requested flow.
+                return Math.Max(0, demand + t[0]);
+            }
+
+            int enter = 0;
+            bool bland = iteration >= 40;
+            for (int j = 1; j <= columns; j++)
+            {
+                if (t[j] > Epsilon && (enter == 0 ||
+                    (bland ? this.nonbasic[j] < this.nonbasic[enter] : t[j] > t[enter] + Epsilon)))
+                {
+                    enter = j;
+                }
+            }
+
+            if (enter == 0)
+            {
+                if (route != null)
+                {
+                    for (int r = 1; r <= rows; r++)
+                    {
+                        int variable = this.basic[r];
+                        if (variable <= columns)
+                        {
+                            route.Add(this.pairList[variable - 1], this.pathList[variable - 1], t[r * width]);
+                        }
+                    }
+
+                    route.RowPrices.AsSpan(0, edgeCount + 1).Clear();
+                    for (int j = 1; j <= columns; j++)
+                    {
+                        int r = this.nonbasic[j] - columns;
+                        if (r > 0 && r <= edgeCount)
+                        {
+                            route.RowPrices[r] = -t[j];
+                        }
+                    }
+
+                    for (int e = 0; e < this.edgeRows.Length; e++)
+                    {
+                        route.Price[e] = route.RowPrices[this.edgeRows[e]];
+                    }
+                }
+
+                return Math.Max(0, demand + t[0]);
+            }
+
+            int leave = 0;
+            double ratio = double.PositiveInfinity;
+            for (int r = 1; r <= rows; r++)
+            {
+                int start = r * width;
+                double a = t[start + enter];
+                if (a > Epsilon)
+                {
+                    double bound = t[start] / a;
+                    if (bound < ratio - Epsilon || (Math.Abs(bound - ratio) <= Epsilon &&
+                        (leave == 0 || this.basic[r] < this.basic[leave])))
+                    {
+                        ratio = bound;
+                        leave = r;
+                    }
+                }
+            }
+
+            if (leave == 0 || iteration > 800)
+            {
+                this.IsOptimal = false;
+                // A feasible partial flow still gives an upper bound on unmet demand.
+                return Math.Max(0, demand + t[0]);
+            }
+
+            int pivot = leave * width;
+            double inv = 1.0 / t[pivot + enter];
+            t[pivot + enter] = 1;
+            for (int j = 0; j <= columns; j++)
+            {
+                t[pivot + j] *= inv;
+            }
+
+            for (int r = 0; r <= rows; r++)
+            {
+                int start = r * width;
+                double multiple = t[start + enter];
+                if (r == leave || Math.Abs(multiple) < Epsilon)
+                {
+                    continue;
+                }
+
+                t[start + enter] = 0;
+                for (int j = 0; j <= columns; j++)
+                {
+                    t[start + j] -= multiple * t[pivot + j];
+                }
+            }
+
+            (this.basic[leave], this.nonbasic[enter]) = (this.nonbasic[enter], this.basic[leave]);
+        }
+    }
+}
+
+internal sealed class FlowRoute
+{
+    private readonly AdversarialSearchInstance data;
+
+    public FlowRoute(AdversarialSearchInstance data)
+        : this(data, false)
+    {
+    }
+
+    public FlowRoute(AdversarialSearchInstance data, bool loads)
+    {
+        this.data = data;
+        this.Load = loads ? new double[data.Edges.Length] : null;
+        this.Served = new double[data.Pairs.Length];
+        this.Price = new double[data.Edges.Length];
+        this.RowPrices = new double[data.Edges.Length + 1];
+    }
+
+    public double[] Load { get; }
+
+    public double[] Served { get; }
+
+    public double[] Price { get; }
+
+    public double[] RowPrices { get; }
+
+    public void Reset()
+    {
+        if (this.Load != null)
+        {
+            Array.Clear(this.Load);
+        }
+
+        Array.Clear(this.Served);
+        Array.Clear(this.Price);
+    }
+
+    public void Add(int pair, int path, double flow)
+    {
+        this.Served[pair] += flow;
+        if (this.Load != null)
+        {
+            foreach (int e in this.data.Pairs[pair].Paths[path])
+            {
+                this.Load[e] += flow;
+            }
+        }
+    }
+}
