new file mode 100644
index 0000000..4fc0670
--- /dev/null
+++ b/project/MetaOptimize/TrafficEngineering/Candidate/LargePairGroups.cs
@@ -0,0 +1,146 @@
+namespace MetaOptimize;
+
+/// <summary>
+/// Groups large-pair choices by their intersection with the complement of a
+/// small pool. Distributed groups of related choices admit common LP bounds.
+/// </summary>
+internal sealed class LargePairGroups
+{
+    private readonly List<int>[] outside;
+    private readonly int[,] next;
+
+    public LargePairGroups(AdversarialSearchInstance data)
+    {
+        int n = data.Pairs.Length;
+        this.Width = Math.Min(11, n);
+        // Spread pool traffic over the network so that routing all of it gives
+        // a useful bound even when a completion uses only a few of its pairs.
+        var usage = new double[n, data.Edges.Length];
+        var accumulated = new double[data.Edges.Length];
+        for (int i = 0; i < n; i++)
+        {
+            foreach (var path in data.Pairs[i].Paths)
+            {
+                foreach (int e in path)
+                {
+                    usage[i, e] += 1.0 / data.Pairs[i].Paths.Length;
+                }
+            }
+        }
+
+        int pool = 0;
+        for (int step = 0; step < this.Width; step++)
+        {
+            int best = -1;
+            double value = double.PositiveInfinity;
+            for (int i = 0; i < n; i++)
+            {
+                if ((pool & (1 << i)) != 0)
+                {
+                    continue;
+                }
+
+                double v = 0;
+                for (int e = 0; e < accumulated.Length; e++)
+                {
+                    v += usage[i, e] * (0.05 + accumulated[e]);
+                }
+
+                if (v < value)
+                {
+                    best = i;
+                    value = v;
+                }
+            }
+
+            pool |= 1 << best;
+            for (int e = 0; e < accumulated.Length; e++)
+            {
+                accumulated[e] += usage[best, e];
+            }
+        }
+
+        this.OptimalCuts = BuildCuts(data);
+        this.Pool = pool;
+        int other = ((1 << n) - 1) ^ pool;
+        this.outside = new List<int>[data.DensityLimit + 1];
+        for (int k = 0; k < this.outside.Length; k++)
+        {
+            this.outside[k] = new List<int>();
+        }
+
+        for (int mask = other; ; mask = (mask - 1) & other)
+        {
+            int count = FlowSolver.Count(mask);
+            if (count < this.outside.Length)
+            {
+                this.outside[count].Add(mask);
+            }
+
+            if (mask == 0)
+            {
+                break;
+            }
+        }
+
+        this.next = new int[data.DensityLimit + 1, data.DensityLimit + 1];
+    }
+
+    public KeyValuePair<int, double>[] OptimalCuts { get; }
+
+    public int Pool { get; }
+
+    public int Width { get; }
+
+    // Unit prices on a few edges give linear lower bounds on the unmet
+    // demand under full-capacity optimal routing, for every demand matrix.
+    private static KeyValuePair<int, double>[] BuildCuts(AdversarialSearchInstance data)
+    {
+        var incidence = new int[data.Edges.Length, 4];
+        for (int i = 0; i < data.Pairs.Length; i++)
+        {
+            var paths = data.Pairs[i].Paths;
+            for (int j = 0; j < 4; j++)
+            {
+                foreach (int e in paths[j < paths.Length ? j : 0])
+                {
+                    incidence[e, j] |= 1 << i;
+                }
+            }
+        }
+
+        var cuts = new Dictionary<int, double>();
+        void Extend(int first, int depth, double cost, int a, int b, int c, int d)
+        {
+            if (depth > 0)
+            {
+                int covered = a & b & c & d;
+                if (data.Levels[2] * Math.Min(data.DensityLimit, FlowSolver.Count(covered)) > cost &&
+                    (!cuts.TryGetValue(covered, out double old) || cost < old))
+                {
+                    cuts[covered] = cost;
+                }
+            }
+
+            if (depth == 3)
+            {
+                return;
+            }
+
+            for (int e = first; e < data.Edges.Length; e++)
+            {
+                Extend(e + 1, depth + 1, cost + data.Edges[e].Capacity,
+                    a | incidence[e, 0], b | incidence[e, 1], c | incidence[e, 2], d | incidence[e, 3]);
+            }
+        }
+
+        Extend(0, 0, 0, 0, 0, 0, 0);
+        var result = new KeyValuePair<int, double>[cuts.Count];
+        ((ICollection<KeyValuePair<int, double>>)cuts).CopyTo(result, 0);
+        return result;
+    }
+
+    public List<int> Outside(int count) => this.outside[count];
+
+    public int Claim(int total, int count, int batch) => Interlocked.Add(ref this.next[total, count], batch) - batch;
+}
diff --git a/project/MetaOptimize/TrafficEngineering/Candidate/PinSearch.cs b/project/MetaOptimize/TrafficEngineering/Candidate/PinSearch.cs
new file mode 100644
index 0000000..b9f1253
