@@ -0,0 +1,846 @@
+namespace MetaOptimize;
+
+using System.Diagnostics;
+using System.Numerics;
+
+/// <summary>
+/// For fixed large pairs, the residual LP deficit is convex in the pinned load.
+/// Bound it across many pin choices at once, then evaluate the combined gap on
+/// choices whose upper bounds still exceed the incumbent.
+/// </summary>
+internal sealed class PinSearch
+{
+    private const double Epsilon = 1e-7;
+    private readonly AdversarialSearchInstance data;
+    private readonly DemandOptimizer optimizer;
+    private readonly LargePairGroups groups;
+    private readonly FlowSolver groupSolver;
+    private readonly FlowRoute groupRoute;
+    private readonly double[] groupWeights;
+    private readonly double[] remaining;
+    private readonly int[] suffixChoices;
+    private readonly FlowSolver solver;
+    private readonly FlowRoute route;
+    private readonly SharedIncumbent global;
+    private readonly Stopwatch timer;
+    private readonly int limitMs;
+    private readonly int n;
+    private readonly int[] pinUsers;
+    private readonly int[] maxPins;
+    private readonly double[] pinGain;
+    private readonly int[] edgeUsers;
+    private readonly ulong[][] paths;
+    private readonly double[] restrictedGain;
+    private readonly int[] gainCounts;
+    private int allowedPins;
+    private readonly double[] capacity;
+    private readonly double[] topWeights;
+    private readonly double[] nominalLossWeight;
+    private readonly double[] jensen;
+    private readonly double[,] suffix;
+    private readonly double[,] rawSuffix;
+    private readonly int[] cutCovered = new int[6];
+    private readonly double[] cutBase = new double[6];
+    private readonly double[] cutPriority = new double[6];
+    private int cutCount;
+    private readonly int[] order;
+    private readonly double[] overall;
+    private int large;
+    private int pins;
+    private int nodes;
+    private int combinations;
+    private double baseLoss;
+    private double best;
+    private bool stop;
+
+    public PinSearch(AdversarialSearchInstance data, DemandOptimizer optimizer, SharedIncumbent global, Stopwatch timer, int limitMs, LargePairGroups groups)
+    {
+        this.data = data;
+        this.optimizer = optimizer;
+        this.global = global;
+        this.timer = timer;
+        this.limitMs = limitMs;
+        this.groups = groups;
+        this.groupSolver = new FlowSolver(data, Math.Min(data.Pairs.Length, data.DensityLimit + groups.Width));
+        this.groupRoute = new FlowRoute(data);
+        this.groupWeights = new double[groups.Width];
+        this.remaining = new double[data.Edges.Length];
+        this.suffixChoices = new int[data.Pairs.Length + 1];
+        this.solver = new FlowSolver(data);
+        this.route = new FlowRoute(data, true);
+        this.n = data.Pairs.Length;
+        this.pinUsers = new int[data.Edges.Length];
+        this.maxPins = new int[data.Edges.Length];
+        for (int e = 0; e < this.maxPins.Length; e++)
+        {
+            this.maxPins[e] = (int)Math.Floor((data.Edges[e].Capacity + Epsilon) / data.Levels[1]);
+        }
+
+        this.pinGain = new double[this.n];
+        this.restrictedGain = new double[this.n];
+        this.gainCounts = new int[data.Edges.Length + 1];
+        this.edgeUsers = new int[data.Edges.Length];
+        this.paths = new ulong[this.n][];
+        var gains = new double[this.n];
+        for (int i = 0; i < this.n; i++)
+        {
+            var paths = data.Pairs[i].Paths;
+            this.paths[i] = new ulong[paths.Length];
+            for (int j = 0; j < paths.Length; j++)
+            {
+                foreach (int e in paths[j])
+                {
+                    this.paths[i][j] |= 1UL << e;
+                    this.edgeUsers[e] |= 1 << i;
+                }
+            }
+
+            foreach (int e in paths[0])
+            {
+                this.pinUsers[e] |= 1 << i;
+            }
+
+            bool unavoidable = true;
+            foreach (var path in paths)
+            {
+                bool crosses = false;
+                foreach (int e in path)
+                {
+                    crosses |= Array.IndexOf(paths[0], e) >= 0;
+                }
+
+                unavoidable &= crosses;
+            }
+
+            gains[i] = this.pinGain[i] = data.Levels[1] * (paths[0].Length - (unavoidable ? 1 : 0));
+        }
+
+        Array.Sort(gains);
+        this.overall = new double[data.DensityLimit + 1];
+        for (int p = 1; p < this.overall.Length; p++)
+        {
+            this.overall[p] = this.overall[p - 1] + gains[this.n - p];
+        }
+
+        this.capacity = new double[data.Edges.Length];
+        this.topWeights = new double[data.DensityLimit];
+        this.nominalLossWeight = new double[this.n];
+        this.jensen = new double[this.n];
+        this.order = new int[this.n];
+        this.suffix = new double[this.n + 1, data.DensityLimit + 1];
+        this.rawSuffix = new double[this.n + 1, data.DensityLimit + 1];
+    }
+
+    public void Run(int worker)
+    {
+        int middle = this.data.DensityLimit / 2;
+        int preferred = worker == 0 ? FlowSolver.Count(this.optimizer.Best.Matrix.Large) : middle + worker - 2;
+        preferred = Math.Clamp(preferred, 1, this.data.DensityLimit - 1);
+        for (int step = 0; step < (2 * this.data.DensityLimit) - 1; step++)
+        {
+            int offset = (step + 1) / 2;
+            int count = (step & 1) == 0 ? preferred + offset : preferred - offset;
+            if (count < 1 || count >= this.data.DensityLimit)
+            {
+                continue;
+            }
+
+            this.pins = this.data.DensityLimit - count;
+            this.best = this.global.Value;
+            if (count * this.data.Levels[2] <= this.best + Epsilon || this.overall[this.pins] <= this.best + Epsilon)
+            {
+                continue;
+            }
+
+            this.allowedPins = 0;
+            for (int i = 0; i < this.n; i++)
+            {
+                if (this.overall[this.pins - 1] + this.pinGain[i] > this.best + Epsilon)
+                {
+                    this.allowedPins |= 1 << i;
+                }
+            }
+
+            for (int outside = 0; outside <= count && !this.stop; outside++)
+            {
+                int take = count - outside;
+                if (take > this.groups.Width)
+                {
+                    continue;
+                }
+
+                var masks = this.groups.Outside(outside);
+                const int batch = 4;
+                int index;
+                while (!this.stop && (index = this.groups.Claim(count, outside, batch)) < masks.Count)
+                {
+                    this.best = this.global.Value;
+                    for (int j = index; j < Math.Min(index + batch, masks.Count); j++)
+                    {
+                        this.SearchGroup(masks[j], this.groups.Pool, take, this.allowedPins & ~masks[j]);
+                    }
+                }
+            }
+
+            if (this.stop)
+            {
+                return;
+            }
+        }
+    }
+
+    private void SearchGroup(int fixedMask, int choices, int take, int permitted)
+    {
+        if (this.stop || ((++this.combinations & 127) == 0 && (this.stop = this.timer.ElapsedMilliseconds >= this.limitMs)))
+        {
+            return;
+        }
+
+        int free = FlowSolver.Count(choices);
+        if (take == 0 || take == free)
+        {
+            this.SearchMask(take == 0 ? fixedMask : fixedMask | choices, permitted);
+            return;
+        }
+
+        int superset = fixedMask | choices;
+        if (free >= 4)
+        {
+            this.WorstCapacities(permitted);
+            // Give every optional pair a common first allocation. Only "take"
+            // optional allocations survive in any one demand matrix.
+            double target = Math.Max(0, this.data.Levels[2] - (this.best / take));
+            this.GreedyGroup(fixedMask, choices, target);
+            if (this.GroupBound(fixedMask, choices, take, null, this.groupRoute.Served) <= this.best + Epsilon)
+            {
+                return;
+            }
+
+            int narrowed = this.RestrictPins(fixedMask, choices, take, permitted);
+            if (narrowed == 0)
+            {
+                return;
+            }
+
+            if (narrowed != permitted)
+            {
+                permitted = narrowed;
+                this.WorstCapacities(permitted);
+            }
+
+            double t = (target + this.data.Levels[2]) * 0.5;
+            double loss = this.groupSolver.Solve(choices, fixedMask, 0, 1, this.capacity, this.groupRoute, t, this.best - ((this.data.Levels[2] - t) * take));
+            if (((this.data.Levels[2] - t) * take) + loss <= this.best + Epsilon ||
+                this.GroupBound(fixedMask, choices, take, null, this.groupRoute.Served) <= this.best + Epsilon)
+            {
+                return;
+            }
+
+            if (free >= 6)
+            {
+                // A dual solution on the full-capacity network bounds OPT for
+                // every subset, while each subset can retain its share of the
+                // full group's feasible routing on the residual network.
+                this.groupSolver.Solve(choices, fixedMask, 0, 1, null, this.route, t);
+                if (this.GroupBound(fixedMask, choices, take, this.route.Price, this.groupRoute.Served) <= this.best + Epsilon)
+                {
+                    return;
+                }
+
+                double nominal = this.GroupBound(fixedMask, choices, take, this.route.Price, this.route.Served);
+                if (nominal <= this.best + Epsilon &&
+                    this.RouteBound(permitted, this.route) + nominal <= this.best + Epsilon)
+                {
+                    return;
+                }
+            }
+        }
+
+        if (take == 1 || take == free - 1)
+        {
+            for (int bits = choices; bits != 0; bits &= bits - 1)
+            {
+                int pivot = bits & -bits;
+                this.SearchMask(take == 1 ? fixedMask | pivot : superset ^ pivot, permitted);
+            }
+
+            return;
+        }
+
+        int bit = choices & -choices;
+        this.SearchGroup(fixedMask | bit, choices ^ bit, take - 1, permitted & ~bit);
+        this.SearchGroup(fixedMask, choices ^ bit, take, permitted);
+    }
+
+    // An edge cannot have a necessary positive price in the residual-flow LP
+    // when all possible large-pair flow on it already fits. Pairs with a path
+    // avoiding every remaining priced edge can then be carried independently.
+    private int RestrictPins(int fixedMask, int choices, int take, int permitted)
+    {
+        if (this.data.Edges.Length > 64)
+        {
+            return permitted;
+        }
+
+        int active = fixedMask | choices;
+        ulong possible;
+        while (true)
+        {
+            possible = 0;
+            for (int e = 0; e < this.edgeUsers.Length; e++)
+            {
+                int users = this.edgeUsers[e] & active;
+                int max = FlowSolver.Count(users & fixedMask) + Math.Min(take, FlowSolver.Count(users & choices));
+                if (this.data.Levels[2] * max > this.capacity[e] + Epsilon)
+                {
+                    possible |= 1UL << e;
+                }
+            }
+
+            int next = active;
+            for (int bits = active; bits != 0; bits &= bits - 1)
+            {
+                int i = FlowSolver.First(bits);
+                foreach (ulong path in this.paths[i])
+                {
+                    if ((path & possible) == 0)
+                    {
+                        next &= ~(1 << i);
+                        break;
+                    }
+                }
+            }
+
+            int maxActive = FlowSolver.Count(next & fixedMask) + Math.Min(take, FlowSolver.Count(next & choices));
+            if (this.data.Levels[2] * maxActive <= this.best + Epsilon)
+            {
+                return 0;
+            }
+
+            if (active == next)
+            {
+                break;
+            }
+
+            active = next;
+        }
+
+        int longest = 0;
+        for (int bits = permitted; bits != 0; bits &= bits - 1)
+        {
+            int i = FlowSolver.First(bits);
+            ulong first = this.paths[i][0] & possible;
+            int saving = BitOperations.PopCount(first);
+            bool avoidable = false;
+            foreach (ulong path in this.paths[i])
+            {
+                avoidable |= (path & first) == 0;
+            }
+
+            if (!avoidable)
+            {
+                saving--;
+            }
+
+            longest = Math.Max(longest, saving);
+            this.gainCounts[saving]++;
+            this.restrictedGain[i] = this.data.Levels[1] * saving;
+        }
+
+        double top = 0;
+        int left = this.pins;
+        double last = 0;
+        for (int j = longest; j >= 0; j--)
+        {
+            int count = Math.Min(left, this.gainCounts[j]);
+            left -= count;
+            if (count > 0 && left == 0)
+            {
+                last = this.data.Levels[1] * j;
+            }
+
+            top += this.data.Levels[1] * j * count;
+            this.gainCounts[j] = 0;
+        }
+
+        if (top <= this.best + Epsilon)
+        {
+            return 0;
+        }
+
+        // The sum of the best p-1 individual gains bounds the help a pin can
+        // obtain from its companions, including when fewer than p are present.
+        int kept = permitted;
+        for (int bits = permitted; bits != 0; bits &= bits - 1)
+        {
+            int i = FlowSolver.First(bits);
+            if (this.restrictedGain[i] + top - last <= this.best + Epsilon)
+            {
+                kept ^= 1 << i;
+            }
+        }
+
+        return kept;
+    }
+
+    private void GreedyGroup(int fixedMask, int choices, double target)
+    {
+        Array.Copy(this.capacity, this.remaining, this.remaining.Length);
+        double high = this.data.Levels[2];
+        for (int bits = fixedMask; bits != 0; bits &= bits - 1)
+        {
+            int i = FlowSolver.First(bits);
+            this.groupRoute.Served[i] = this.RoutePaths(i, high);
+        }
+
+        for (int bits = choices; bits != 0; bits &= bits - 1)
+        {
+            int i = FlowSolver.First(bits);
+            this.groupRoute.Served[i] = this.RoutePaths(i, target);
+        }
+
+        for (int bits = choices; bits != 0; bits &= bits - 1)
+        {
+            int i = FlowSolver.First(bits);
+            this.groupRoute.Served[i] += this.RoutePaths(i, high - this.groupRoute.Served[i]);
+        }
+    }
+
+    private double RoutePaths(int i, double demand)
+    {
+        double remainingDemand = demand;
+        foreach (var path in this.data.Pairs[i].Paths)
+        {
+            double flow = remainingDemand;
+            foreach (int e in path)
+            {
+                flow = Math.Min(flow, this.remaining[e]);
+            }
+
+            if (flow > 0)
+            {
+                foreach (int e in path)
+                {
+                    this.remaining[e] -= flow;
+                }
+
+                remainingDemand -= flow;
+                if (remainingDemand < Epsilon)
+                {
+                    break;
+                }
+            }
+        }
+
+        return demand - remainingDemand;
+    }
+
+    private bool GreedyBound(int mask)
+    {
+        Array.Copy(this.capacity, this.remaining, this.remaining.Length);
+        double unmet = 0;
+        double high = this.data.Levels[2];
+        for (int bits = mask; bits != 0; bits &= bits - 1)
+        {
+            unmet += high - this.RoutePaths(FlowSolver.First(bits), high);
+            if (unmet > this.best + Epsilon)
+            {
+                return false;
+            }
+        }
+
+        return true;
+    }
+
+    private double GroupBound(int fixedMask, int choices, int take, double[] price, double[] served)
+    {
+        double value = 0;
+        if (price != null)
+        {
+            for (int e = 0; e < price.Length; e++)
+            {
+                value += price[e] * this.data.Edges[e].Capacity;
+            }
+        }
+
+        int count = 0;
+        for (int bits = fixedMask | choices; bits != 0; bits &= bits - 1)
+        {
+            int i = FlowSolver.First(bits);
+            double w = price == null ? 0 : this.PathPrice(i, price);
+            double term = (this.data.Levels[2] * (1 - w)) - served[i];
+            if ((fixedMask & (1 << i)) != 0)
+            {
+                value += term;
+            }
+            else
+            {
+                this.groupWeights[count++] = term;
+            }
+        }
+
+        Array.Sort(this.groupWeights, 0, count);
+        for (int i = count - take; i < count; i++)
+        {
+            value += this.groupWeights[i];
+        }
+
+        return value;
+    }
+
+    // Restrict the nominal path flow to a subset, then remove any excess on
+    // pinned edges. Convexity bounds the excess for a mixture of pin scenarios.
+    private double RouteBound(int permitted, FlowRoute nominal)
+    {
+        double lo = this.data.Levels[1];
+        Array.Clear(this.topWeights, 0, this.pins);
+        for (int bits = permitted; bits != 0; bits &= bits - 1)
+        {
+            int i = FlowSolver.First(bits);
+            double excess = 0;
+            foreach (int e in this.data.Pairs[i].Paths[0])
+            {
+                excess += Math.Max(0, nominal.Load[e] + (lo * this.pins) - this.data.Edges[e].Capacity);
+            }
+
+            double penalty = lo * this.PathPrice(i, nominal.Price);
+            this.nominalLossWeight[i] = penalty;
+            this.jensen[i] = (excess / this.pins) - penalty;
+            this.InsertWeight(this.jensen[i]);
+        }
+
+        return this.TopSum();
+    }
+
+    private void InsertWeight(double value)
+    {
+        int pos = this.pins - 1;
+        if (value <= this.topWeights[pos])
+        {
+            return;
+        }
+
+        while (pos > 0 && value > this.topWeights[pos - 1])
+        {
+            this.topWeights[pos] = this.topWeights[pos - 1];
+            pos--;
+        }
+
+        this.topWeights[pos] = value;
+    }
+
+    private double TopSum()
+    {
+        double sum = 0;
+        for (int j = 0; j < this.pins; j++)
+        {
+            sum += this.topWeights[j];
+        }
+
+        return sum;
+    }
+
+    private double PathPrice(int i, double[] price)
+    {
+        double w = 1;
+        foreach (var path in this.data.Pairs[i].Paths)
+        {
+            double cost = 0;
+            foreach (int e in path)
+            {
+                cost += price[e];
+            }
+
+            w = Math.Min(w, cost);
+        }
+
+        return w;
+    }
+
+    private void WorstCapacities(int permitted)
+    {
+        double lo = this.data.Levels[1];
+        for (int e = 0; e < this.pinUsers.Length; e++)
+        {
+            int worst = Math.Min(this.pins, Math.Min(this.maxPins[e], FlowSolver.Count(this.pinUsers[e] & permitted)));
+            this.capacity[e] = this.data.Edges[e].Capacity - (lo * worst);
+        }
+    }
+
+    private void SearchMask(int mask, int permitted)
+    {
+        this.large = mask;
+        permitted &= ~mask;
+        if (permitted == 0 || this.stop)
+        {
+            return;
+        }
+
+        double lo = this.data.Levels[1];
+        this.WorstCapacities(permitted);
+        if (this.GreedyBound(mask))
+        {
+            return;
+        }
+
+        int narrowed = this.RestrictPins(mask, 0, 0, permitted);
+        if (narrowed == 0)
+        {
+            return;
+        }
+
+        if (narrowed != permitted)
+        {
+            permitted = narrowed;
+            this.WorstCapacities(permitted);
+        }
+
+        double worstLoss = this.solver.Solve(0, mask, 0, 1, this.capacity, null, -1, this.best);
+        if (worstLoss <= this.best + Epsilon)
+        {
+            return;
+        }
+
+        this.baseLoss = this.solver.Solve(0, mask, 0, 1, null, this.route);
+        if (!this.solver.IsOptimal || worstLoss - this.baseLoss <= this.best + Epsilon)
+        {
+            return;
+        }
+
+        double top = this.RouteBound(permitted, this.route);
+        if (top <= this.best + Epsilon)
+        {
+            return;
+        }
+
+        for (int e = 0; e < this.capacity.Length; e++)
+        {
+            this.capacity[e] = this.data.Edges[e].Capacity;
+        }
+
+        // A set of at most p pins is a convex combination of individual
+        // shortest paths, each assigned p copies of the pin size, and blanks.
+        double companions = top - this.topWeights[this.pins - 1];
+        int count = 0;
+        for (int bits = permitted; bits != 0; bits &= bits - 1)
+        {
+            int i = FlowSolver.First(bits);
+            if (this.jensen[i] + companions <= this.best + Epsilon)
+            {
+                continue;
+            }
+
+            this.order[count++] = i;
+        }
+
+        // Refine the upper bounds for the terms that dominate the sum.
+        Array.Sort(this.order, 0, count, Comparer<int>.Create((a, b) => this.jensen[b].CompareTo(this.jensen[a])));
+        for (int j = 0; j < count; j++)
+        {
+            int i = this.order[j];
+            if (this.jensen[i] + companions <= this.best + Epsilon)
+            {
+                break;
+            }
+
+            double extra = 0;
+            var paths = this.data.Pairs[i].Paths;
+            foreach (int e in paths[0])
+            {
+                double cap = this.data.Edges[e].Capacity - (lo * this.pins);
+                // In a feasible packing LP the edge prices can be capped at one.
+                // This also bounds the affine loss extension at negative capacities.
+                extra += Math.Max(0, -cap);
+                this.capacity[e] = Math.Max(0, cap);
+            }
+
+            double cutoff = this.baseLoss - extra + (this.pins * (this.best - companions + this.nominalLossWeight[i]));
+            double delta = this.solver.Solve(0, mask, 0, 1, this.capacity, null, -1, cutoff) + extra - this.baseLoss;
+            foreach (int e in paths[0])
+            {
+                this.capacity[e] = this.data.Edges[e].Capacity;
+            }
+
+            this.jensen[i] = Math.Min(this.jensen[i], (delta / this.pins) - this.nominalLossWeight[i]);
+            Array.Clear(this.topWeights, 0, this.pins);
+            for (int k = 0; k < count; k++)
+            {
+                this.InsertWeight(this.jensen[this.order[k]]);
+            }
+
+            top = this.TopSum();
+            if (top <= this.best + Epsilon)
+            {
+                return;
+            }
+
+            companions = top - this.topWeights[this.pins - 1];
+        }
+
+        // As the weights are sorted, the best completion of each linear bound
+        // consists of the next available positive weights.
+        Array.Sort(this.order, 0, count, Comparer<int>.Create((a, b) => this.jensen[b].CompareTo(this.jensen[a])));
+        this.SelectCuts(permitted);
+        for (int k = 0; k <= this.pins; k++)
+        {
+            this.rawSuffix[count, k] = 0;
+        }
+
+        this.suffixChoices[count] = 0;
+        for (int p = count - 1; p >= 0; p--)
+        {
+            this.suffixChoices[p] = this.suffixChoices[p + 1] | (1 << this.order[p]);
+            double value = Math.Max(0, this.jensen[this.order[p]]);
+            for (int k = 1; k <= this.pins; k++)
+            {
+                this.suffix[p, k] = value + (p + 1 < count ? this.suffix[p + 1, k - 1] : 0);
+                double raw = this.jensen[this.order[p]] + this.nominalLossWeight[this.order[p]];
+                this.rawSuffix[p, k] = Math.Max(this.rawSuffix[p + 1, k], raw + this.rawSuffix[p + 1, k - 1]);
+            }
+        }
+
+        this.Assign(0, count, this.pins, 0, 0, this.baseLoss, this.baseLoss, worstLoss);
+    }
+
+    private void SelectCuts(int permitted)
+    {
+        this.cutCount = 0;
+        int numPossible = FlowSolver.Count(permitted);
+        foreach (var cut in this.groups.OptimalCuts)
+        {
+            double baseValue = (this.data.Levels[2] * FlowSolver.Count(this.large & cut.Key)) - cut.Value;
+            int priced = FlowSolver.Count(permitted & cut.Key);
+            double upper = baseValue + (this.data.Levels[1] * Math.Min(this.pins, priced));
+            if (upper <= this.baseLoss + Epsilon)
+            {
+                continue;
+            }
+
+            double expected = baseValue + (this.data.Levels[1] * this.pins * priced / numPossible);
+            double priority = (0.6 * expected) + (0.4 * upper);
+            int pos = this.cutCount;
+            if (pos == this.cutCovered.Length)
+            {
+                if (priority <= this.cutPriority[pos - 1])
+                {
+                    continue;
+                }
+
+                pos--;
+            }
+            else
+            {
+                this.cutCount++;
+            }
+
+            while (pos > 0 && priority > this.cutPriority[pos - 1])
+            {
+                this.cutBase[pos] = this.cutBase[pos - 1];
+                this.cutPriority[pos] = this.cutPriority[pos - 1];
+                this.cutCovered[pos] = this.cutCovered[pos - 1];
+                pos--;
+            }
+
+            this.cutBase[pos] = baseValue;
+            this.cutPriority[pos] = priority;
+            this.cutCovered[pos] = cut.Key;
+        }
+    }
+
+    private void Assign(int start, int count, int slots, int small, double sum, double dualLower, double optLower, double worstLoss)
+    {
+        if (this.stop || worstLoss - optLower <= this.best + Epsilon)
+        {
+            return;
+        }
+
+        if ((++this.nodes & 2047) == 0 && this.timer.ElapsedMilliseconds >= this.limitMs)
+        {
+            this.stop = true;
+            return;
+        }
+
+        double raw = sum + dualLower;
+        int extras = Math.Min(slots, count - start);
+        for (int j = 0; j < this.cutCount; j++)
+        {
+            int covered = this.cutCovered[j];
+            double floor = this.cutBase[j] + (this.data.Levels[1] * FlowSolver.Count(small & covered));
+            int free = FlowSolver.Count(this.suffixChoices[start] & ~covered);
+            optLower = Math.Max(optLower, floor);
+            bool viable = false;
+            for (int added = 0; added <= extras; added++)
+            {
+                double loss = Math.Min(worstLoss, raw + this.rawSuffix[start, added]);
+                double opt = Math.Max(optLower, floor + (this.data.Levels[1] * Math.Max(0, added - free)));
+                if (loss - opt > this.best + Epsilon)
+                {
+                    viable = true;
+                    break;
+                }
+            }
+
+            if (!viable)
+            {
+                return;
+            }
+        }
+
+        if (small != 0 && slots >= 2 && start + slots + 2 < count &&
+            ((this.pins - slots) & 1) == 1)
+        {
+            // Adding fixed pins and removing choices tightens the simultaneous
+            // worst-case edge loads used for the whole family of completions.
+            int allowed = this.suffixChoices[start];
+            for (int e = 0; e < this.pinUsers.Length; e++)
+            {
+                int fixedPins = FlowSolver.Count(small & this.pinUsers[e]);
+                if (fixedPins > this.maxPins[e])
+                {
+                    return;
+                }
+
+                int extra = Math.Min(slots, FlowSolver.Count(allowed & this.pinUsers[e]));
+                this.capacity[e] = this.data.Edges[e].Capacity -
+                    (this.data.Levels[1] * Math.Min(this.maxPins[e], fixedPins + extra));
+            }
+
+            worstLoss = Math.Min(worstLoss, this.solver.Solve(0, this.large, 0, 1, this.capacity, null, -1, this.best + optLower));
+            if (worstLoss - optLower <= this.best + Epsilon)
+            {
+                return;
+            }
+        }
+
+        if (Math.Min(worstLoss, raw) - optLower > this.best + Epsilon)
+        {
+            var score = this.optimizer.Score(new Matrix(small, this.large));
+            if (score.Gap > this.best + Epsilon)
+            {
+                this.global.Improve(score.Gap);
+                this.best = this.global.Value;
+            }
+
+            optLower = Math.Max(optLower, score.OptimalLoss);
+            if (worstLoss - optLower <= this.best + Epsilon)
+            {
+                return;
+            }
+        }
+
+        if (slots == 0)
+        {
+            return;
+        }
+
+        for (int p = start; p < count && sum + this.suffix[p, slots] > this.best + Epsilon; p++)
+        {
+            int i = this.order[p];
+            // The nominal dual lower bound adds linearly with pins. An exact
+            // partial optimal loss is also a lower bound for its supersets.
+            double lower = dualLower + this.nominalLossWeight[i];
+            this.Assign(p + 1, count, slots - 1, small | (1 << i), sum + this.jensen[i],
+                lower, Math.Max(optLower, lower), worstLoss);
+        }
+    }
+}
